/* ===== Reset & Normalize ===== */
html{box-sizing:border-box;-ms-text-size-adjust:100%;-webkit-text-size-adjust:100%;overflow-x:hidden;font-size:16px}
*,*:before,*:after{box-sizing:inherit}
body{margin:0;font-family:'Segoe UI',Verdana,sans-serif;font-size:15px;line-height:1.5;color:#000;background-color:#fff;min-height:100vh;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
article,aside,details,figcaption,figure,footer,header,main,menu,nav,section{display:block}
summary{display:list-item}
audio,canvas,progress,video{display:inline-block}
progress{vertical-align:baseline}
audio:not([controls]){display:none;height:0}
[hidden],template{display:none}
a{background-color:transparent;color:inherit;text-decoration:none}
a:active,a:hover{outline-width:0}
abbr[title]{border-bottom:none;text-decoration:underline;text-decoration:underline dotted}
b,strong{font-weight:bolder}
dfn{font-style:italic}
mark{background:#ff0;color:#000}
small{font-size:80%}
sub,sup{font-size:75%;line-height:0;position:relative;vertical-align:baseline}
sub{bottom:-0.25em}
sup{top:-0.5em}
figure{margin:1em 40px}
img{border-style:none;vertical-align:middle;max-width:100%;height:auto}
code,kbd,pre,samp{font-family:monospace,monospace;font-size:1em}
hr{box-sizing:content-box;height:0;overflow:visible;border:0;border-top:1px solid #eee;margin:20px 0}
button,input,select,textarea,optgroup{font:inherit;margin:0}
optgroup{font-weight:bold}
button,input{overflow:visible}
button,select{text-transform:none}
button,[type=button],[type=reset],[type=submit]{-webkit-appearance:button;cursor:pointer}
button::-moz-focus-inner,[type=button]::-moz-focus-inner,[type=reset]::-moz-focus-inner,[type=submit]::-moz-focus-inner{border-style:none;padding:0}
button:-moz-focusring,[type=button]:-moz-focusring,[type=reset]:-moz-focusring,[type=submit]:-moz-focusring{outline:1px dotted ButtonText}
fieldset{border:1px solid #c0c0c0;margin:0 2px;padding:.35em .625em .75em}
legend{color:inherit;display:table;max-width:100%;padding:0;white-space:normal}
textarea{overflow:auto}
[type=checkbox],[type=radio]{padding:0}
[type=number]::-webkit-inner-spin-button,[type=number]::-webkit-outer-spin-button{height:auto}
[type=search]{-webkit-appearance:textfield;outline-offset:-2px}
[type=search]::-webkit-search-decoration{-webkit-appearance:none}
::-webkit-file-upload-button{-webkit-appearance:button;font:inherit}
h1,h2,h3,h4,h5,h6{font-family:'Segoe UI',Arial,sans-serif;font-weight:400;margin:10px 0}
h1{font-size:clamp(2rem,1.5rem+2vw,2.25rem)}
h2{font-size:clamp(1.75rem,1.35rem+1.5vw,1.875rem)}
h3{font-size:clamp(1.4rem,1.15rem+1vw,1.5rem)}
h4{font-size:clamp(1.2rem,1.05rem+0.6vw,1.25rem)}
h5{font-size:clamp(1.05rem,0.98rem+0.35vw,1.125rem)}
h6{font-size:clamp(0.95rem,0.92rem+0.2vw,1rem)}
p{margin:0}
ul,ol{margin:0;padding:0;list-style:none}


