.ic-text-clip{overflow:hidden!important;text-overflow:clip!important;white-space:nowrap!important}
.ic-line-clamp-1{display:-webkit-box!important;-webkit-box-orient:vertical!important;-webkit-line-clamp:1!important;overflow:hidden!important}
.ic-line-clamp-2{display:-webkit-box!important;-webkit-box-orient:vertical!important;-webkit-line-clamp:2!important;overflow:hidden!important}
