.ic-modal-backdrop{position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.5);z-index:1040!important}
.ic-modal-dialog{position:relative;width:auto;margin:1.75rem;max-width:500px;z-index:1060!important}
.ic-modal-content{position:relative;background:#fff;border:1px solid rgba(0,0,0,0.2);border-radius:0.375rem;outline:0;box-shadow:0 0.5rem 1rem rgba(0,0,0,0.15)!important}
.ic-modal-header{display:flex;align-items:center;justify-content:space-between;padding:1rem;border-bottom:1px solid #dee2e6!important}
.ic-modal-body{position:relative;padding:1rem!important}
.ic-modal-footer{display:flex;align-items:center;justify-content:flex-end;padding:1rem;border-top:1px solid #dee2e6;gap:0.5rem!important}
.ic-modal-close{background:none;border:0;font-size:1.5rem;font-weight:bold;cursor:pointer;opacity:0.5!important}
.ic-modal-sm{max-width:300px!important}
.ic-modal-lg{max-width:800px!important}
.ic-modal-center{align-items:center;min-height:calc(100% - 3.5rem)!important}
.ic-tooltip{position:relative;display:inline-block!important}
.ic-tooltip-text{position:absolute;visibility:hidden;background:#000;color:#fff;padding:0.25rem 0.5rem;border-radius:0.25rem;font-size:0.875rem;white-space:nowrap;z-index:1070;opacity:0;transition:opacity 0.3s!important}
.ic-tooltip:hover .ic-tooltip-text{visibility:visible;opacity:1!important}
.ic-tooltip-top .ic-tooltip-text{bottom:100%;left:50%;transform:translateX(-50%);margin-bottom:0.25rem!important}
.ic-tooltip-bottom .ic-tooltip-text{top:100%;left:50%;transform:translateX(-50%);margin-top:0.25rem!important}
.ic-tooltip-left .ic-tooltip-text{right:100%;top:50%;transform:translateY(-50%);margin-right:0.25rem!important}
.ic-tooltip-right .ic-tooltip-text{left:100%;top:50%;transform:translateY(-50%);margin-left:0.25rem!important}
.ic-accordion{overflow:hidden!important}
.ic-accordion-item{border:1px solid #dee2e6;border-bottom:0!important}
.ic-accordion-item:last-child{border-bottom:1px solid #dee2e6!important}
.ic-accordion-header{padding:0.75rem 1.25rem;background:#f8f9fa;cursor:pointer;font-weight:500!important}
.ic-accordion-body{padding:1rem 1.25rem;display:none!important}
.ic-accordion-open .ic-accordion-body{display:block!important}
.ic-tabs{border:1px solid #dee2e6;border-radius:0.25rem;overflow:hidden!important}
.ic-tab-list{display:flex;list-style:none;margin:0;padding:0;border-bottom:1px solid #dee2e6!important}
.ic-tab{padding:0.5rem 1rem;cursor:pointer;border:1px solid transparent!important}
.ic-tab-active{background:#f8f9fa;border-color:#dee2e6 #dee2e6 #fff!important}
.ic-tab-disabled{opacity:0.5;cursor:not-allowed!important}
.ic-tab-panel{padding:1rem!important}
.ic-breadcrumb{display:flex;list-style:none;padding:0.75rem 1rem;margin-bottom:1rem;background:#f8f9fa;border-radius:0.25rem!important}
.ic-breadcrumb-item{display:flex;align-items:center!important}
.ic-breadcrumb-item:not(:last-child)::after{content:"/";margin:0 0.5rem;opacity:0.5!important}
.ic-breadcrumb-item a{color:#007bff;text-decoration:none!important}
.ic-breadcrumb-item.active{color:#6c757d!important}
.ic-pagination{display:flex;list-style:none;padding-left:0;margin:0!important}
.ic-page-item{margin:0 0.125rem!important}
.ic-page-link{display:block;padding:0.5rem 0.75rem;border:1px solid #dee2e6;color:#007bff;text-decoration:none;border-radius:0.25rem!important}
.ic-page-item.ic-page-active .ic-page-link{background:#007bff;color:#fff;border-color:#007bff!important}
.ic-page-item.ic-page-disabled .ic-page-link{color:#6c757d;pointer-events:none;cursor:not-allowed!important}
.ic-jumbotron{padding:2rem 1rem;margin-bottom:2rem;background:#e9ecef;border-radius:0.5rem!important}
.ic-jumbotron-fluid{padding-right:0;padding-left:0;border-radius:0!important}
.ic-jumbotron-title{font-size:2.5rem;font-weight:300!important}
.ic-jumbotron-subtitle{font-size:1.25rem;font-weight:300!important}
.ic-spinner{display:inline-block;width:2rem;height:2rem;vertical-align:text-bottom;border:0.25em solid currentColor;border-right-color:transparent;border-radius:50%;animation:ic-spin 0.75s linear infinite!important}
.ic-spinner-grow{width:2rem;height:2rem;background:currentColor;border-radius:50%;animation:ic-grow 0.75s linear infinite!important}
.ic-spinner-sm{width:1rem;height:1rem!important}
.ic-spinner-lg{width:3rem;height:3rem!important}
.ic-spinner-red{color:#ef4444!important}
.ic-spinner-blue{color:#3b82f6!important}
.ic-spinner-green{color:#22c55e!important}
.ic-spinner-purple{color:#a855f7!important}
.ic-spinner-orange{color:#f97316!important}
.ic-dropdown{position:relative;display:inline-block!important}
.ic-dropdown-toggle::after{display:inline-block;margin-left:0.255em;vertical-align:0.255em;content:"";border-top:0.3em solid;border-right:0.3em solid transparent;border-bottom:0;border-left:0.3em solid transparent!important}
.ic-dropdown-menu{position:absolute;top:100%;left:0;display:none;min-width:10rem;padding:0.5rem 0;margin:0.125rem 0;background:#fff;border:1px solid rgba(0,0,0,0.15);border-radius:0.25rem;box-shadow:0 0.5rem 1rem rgba(0,0,0,0.15);z-index:1000!important}
.ic-dropdown:hover .ic-dropdown-menu{display:block!important}
.ic-dropdown-item{display:block;padding:0.25rem 1.5rem;color:#212529;text-decoration:none!important}
.ic-dropdown-item:hover{background:#f8f9fa!important}
.ic-dropdown-right{left:auto;right:0!important}
.ic-dropdown-up{top:auto;bottom:100%!important}
.ic-hero{padding:4rem 2rem;text-align:center;background:#f8f9fa!important}
.ic-pricing{text-align:center!important}
.ic-price{font-size:2.5rem;font-weight:bold!important}
@keyframes ic-spin{to{transform:rotate(360deg)}}
@keyframes ic-grow{0%{transform:scale(0);opacity:0}50%{opacity:1}100%{transform:scale(1);opacity:0}}

